from pathlib import Path
import base64, hashlib, json, re, shutil, subprocess
ROOT=Path("/tmp/macro-hk-ipo-f2-11085-20261112")
PIN="e752cc8a98a871ce67f4f4a4c98b014f824d0e4a"
REPO="mastermindx-market-intelligence/macro"
GH="/opt/homebrew/bin/gh"
def api(path):return json.loads(subprocess.check_output([GH,"api","repos/"+REPO+"/"+path],stderr=subprocess.PIPE))
def blob(raw):return hashlib.sha1(b"blob "+str(len(raw)).encode()+b"\0"+raw).hexdigest()
index=json.loads((ROOT/"source-index.json").read_text())
manifest=json.loads((ROOT/"input-manifest.json").read_text())
assert not (ROOT/"input-manifest-initial.json").exists(),"Reconcile literal input extension before replay"
shutil.copyfile(ROOT/"input-manifest.json",ROOT/"input-manifest-initial.json")
added=[]
def obtain(path):
    sha=index[path]["sha"]
    raw=None
    for cache in [ROOT/"before",Path("/tmp/macro-ivspread11080-proof-20261111/before"),Path("/tmp/macro-finra11061-native-pages-20261112/source")]:
        p=cache/path
        if p.is_file() and blob(p.read_bytes())==sha:
            raw=p.read_bytes();origin=str(p);break
    if raw is None:
        obj=api("git/blobs/"+sha);raw=base64.b64decode(obj["content"]);origin="GitHub git/blobs/"+sha
    assert blob(raw)==sha
    for stage in ["before","after"]:
        p=ROOT/stage/path
        if p.exists():assert p.read_bytes()==raw,"Refuse to overwrite owned changed source "+path
        else:p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(raw)
    manifest["files"][path]={"blob":sha,"bytes":len(raw),"sha256":hashlib.sha256(raw).hexdigest(),"origin":origin}
    added.append(path)
for p in ["engine/axes.py","engine/conditions.py","engine/regime.py","engine/equity_alloc.py","tests/test_ipo_prospectus_terms.py"]:
    if p not in manifest["files"]:obtain(p)
todo=["templates/ipo.html.j2"];seen=set()
while todo:
    path=todo.pop()
    if path in seen:continue
    seen.add(path)
    text=(ROOT/"before"/path).read_text()
    for name in re.findall(r'{%\s*(?:include|extends|import|from)\s+["\']([^"\']+)["\']',text):
        child="templates/"+name
        if child not in manifest["files"]:obtain(child)
        todo.append(child)
owning=ROOT/"owning-inputs";owning.mkdir()
data={}
for path in ["data/ipo/lockups.parquet","data/ipo/calendar.parquet","data/yahoo/CRCL.parquet"]:
    meta=api("contents/"+path+"?ref="+PIN);sha=meta["sha"]
    raw=base64.b64decode(meta["content"]) if meta.get("encoding")=="base64" and meta.get("content") else base64.b64decode(api("git/blobs/"+sha)["content"])
    assert blob(raw)==sha
    dest=owning/path.removeprefix("data/");dest.parent.mkdir(parents=True,exist_ok=True);dest.write_bytes(raw)
    data[path]={"blob":sha,"bytes":len(raw),"sha256":hashlib.sha256(raw).hexdigest(),"source_commit":PIN}
for path in manifest["retained_inputs"]:
    dest=owning/path.removeprefix("data/");dest.parent.mkdir(parents=True,exist_ok=True)
    shutil.copyfile(ROOT/"retained"/path,dest)
for name in ["tests-after.json","tests-after.log"]:
    shutil.copyfile(ROOT/name,ROOT/(name.replace("-after","-after-attempt1")))
manifest["owning_suite_literal_inputs"]=data
manifest["literal_template_closure"]=sorted(seen)
manifest["literal_input_extension"]=added
(ROOT/"input-manifest.json").write_text(json.dumps(manifest,indent=2,sort_keys=True)+"\n")
print(json.dumps({"added_source_paths":added,"source_files":len(manifest["files"]),"templates":sorted(seen),
                  "owning_data":data,"manifest_sha256":hashlib.sha256((ROOT/"input-manifest.json").read_bytes()).hexdigest()},sort_keys=True))
